// Parser l'événement Brevo
// Brevo envoie un tableau d'événements
const body = $input.first().json.body || $input.first().json;
const events = Array.isArray(body) ? body : [body];

return events.map(event => ({
  json: {
    event_type:   event.event || '',
    email:        event.email || '',
    timestamp:    event.ts_event || event.date || new Date().toISOString(),
    message_id:   event['message-id'] || '',
    prospect_id:  event['X-Prospect-ID'] || event.headers?.['X-Prospect-ID'] || '',
    relance_type: event['X-Relance-Type'] || event.headers?.['X-Relance-Type'] || 'email_initial',
    tag:          (event.tags || []).join(',')
  }
}));

// Calculer les nouveaux compteurs
const event     = $('Parser événement Brevo').first().json;
const prospect  = $input.first().json;

if (!prospect || !prospect.ID) {
  return [{ json: { _not_found: true } }];
}

const isClick   = event.event_type === 'click';
const isOpen    = event.event_type === 'open' || event.event_type === 'opened';
const isReply   = event.event_type === 'reply';

const nb_ouvertures = parseInt(prospect.NB_OUVERTURES || '0') + (isOpen ? 1 : 0);
const nb_clics      = parseInt(prospect.NB_CLICS      || '0') + (isClick ? 1 : 0);

// Seuil : 3 ouvertures ou 1 clic = prospect chaud
const SEUIL_OUVERTURES = 3;
const est_chaud = nb_ouvertures >= SEUIL_OUVERTURES || nb_clics >= 1 || isReply;
const statut_actuel = prospect.STATUT || '';
const deja_chaud = ['chaud', 'converti'].includes(statut_actuel);

return [{ json: {
  ...prospect,
  event_type:         event.event_type,
  nb_ouvertures,
  nb_clics,
  est_chaud,
  deja_chaud,
  alerter:            est_chaud && !deja_chaud,
  nouveau_statut:     est_chaud ? 'chaud' : statut_actuel,
  timestamp_action:   new Date().toISOString()
} }];

// Générer l'alerte prospect chaud via Claude
const p = $input.first().json;

const prompt = `Génère une notification courte (50 mots maximum) pour alerter un commercial que ${p.PRENOM || 'le dirigeant'} de ${p.ENTREPRISE} (${p.SECTEUR}, ${p.VILLE}) est un prospect chaud.

Faits : il a ouvert l'email ${p.nb_ouvertures} fois, cliqué ${p.nb_clics} fois. Son score est ${p.SCORE}/100.

Formule une suggestion d'action immédiate et concrète. Ton : bref, actionnable, sans émojis excessifs.`;

return [{ json: { ...p, alertPrompt: prompt } }];

